【英语二 写作格式规范 - 小作文格式规范，涵盖各类应用文的格式要求】
{
  "module": "writing_knowledge",
  "type": "format_guidelines",
  "subtype": "small_essay",
  "description": "小作文格式规范，涵盖各类应用文的格式要求",
  "formats": [
    {
      "type": "letter",
      "name_cn": "书信（通用）",
      "required_elements": [
        {
          "element": "salutation",
          "name_cn": "称呼",
          "position": "首行顶格",
          "examples": [
            "Dear Professor Smith,",
            "Dear Sir or Madam,",
            "Dear Editor,",
            "Dear Friends,"
          ],
          "rules": [
            "称呼后用逗号",
            "Dear后首字母大写",
            "不认识收信人用 Dear Sir or Madam"
          ]
        },
        {
          "element": "body",
          "name_cn": "正文",
          "position": "称呼下一行缩进或顶格",
          "rules": [
            "通常分2-3段",
            "每段首行缩进4个字母或采用齐头式",
            "要点明确，逻辑清晰"
          ]
        },
        {
          "element": "closing",
          "name_cn": "结束语",
          "position": "正文下一行右侧",
          "examples": [
            "Yours sincerely,",
            "Yours faithfully,",
            "Yours truly,",
            "Best regards,"
          ],
          "rules": [
            "认识收信人用 Yours sincerely",
            "不认识收信人用 Yours faithfully",
            "结束语后用逗号"
          ]
        },
        {
          "element": "signature",
          "name_cn": "署名",
          "position": "结束语下一行",
          "rules": [
            "统一使用 Li Ming",
            "不能使用真实姓名",
            "不需要日期"
          ]
        }
      ],
      "common_format_errors": [
        "缺少称呼直接写正文",
        "缺少结束语和署名",
        "称呼后用句号而非逗号",
        "署名使用真实姓名",
        "Yours sincerely 中 sincerely 首字母大写（应小写）",
        "结束语 Sincerely yours 也可接受但不如 Yours sincerely 规范"
      ]
    },
    {
      "type": "formal_letter",
      "name_cn": "正式书信",
      "applicable_subtypes": [
        "投诉信",
        "求职信",
        "写给不认识的人"
      ],
      "salutation_examples": [
        "Dear Sir or Madam,",
        "Dear Mr./Ms. [Name],",
        "To Whom It May Concern,"
      ],
      "closing_examples": [
        "Yours faithfully,",
        "Yours sincerely,"
      ],
      "tone": "正式，避免口语化表达和缩写（如 don't → do not）"
    },
    {
      "type": "informal_letter",
      "name_cn": "非正式书信（写给朋友/同学）",
      "applicable_subtypes": [
        "感谢信（朋友间）",
        "祝贺信",
        "建议信（朋友间）"
      ],
      "salutation_examples": [
        "Dear [First Name],",
        "Dear Friends,"
      ],
      "closing_examples": [
        "Yours sincerely,",
        "Best wishes,",
        "Best regards,"
      ],
      "tone": "可以较为轻松，但考研作文仍建议偏正式"
    },
    {
      "type": "notice",
      "name_cn": "通知/告示",
      "required_elements": [
        {
          "element": "title",
          "name_cn": "标题",
          "position": "居中",
          "examples": [
            "NOTICE",
            "Notice",
            "Announcement",
            "Volunteers Wanted"
          ],
          "rules": [
            "标题居中大写或首字母大写",
            "标题简洁明了"
          ]
        },
        {
          "element": "body",
          "name_cn": "正文",
          "position": "标题下方",
          "rules": [
            "说明活动目的/背景",
            "提供时间、地点、活动内容等具体信息",
            "说明参与方式或注意事项",
            "通常2-3段"
          ]
        },
        {
          "element": "contact_info",
          "name_cn": "联系方式",
          "position": "正文末尾",
          "rules": [
            "提供联系方式或报名方式",
            "可选"
          ]
        },
        {
          "element": "organization",
          "name_cn": "署名单位",
          "position": "右下角",
          "examples": [
            "The Student Union",
            "The Postgraduate Association",
            "The Library"
          ],
          "rules": [
            "统一使用指定的组织名称"
          ]
        },
        {
          "element": "date",
          "name_cn": "日期",
          "position": "署名下方",
          "examples": [
            "October 7, 2026",
            "Oct. 7, 2026"
          ],
          "rules": [
            "格式统一即可"
          ]
        }
      ],
      "common_format_errors": [
        "缺少标题",
        "写成了书信格式（用了 Dear...）",
        "缺少署名单位",
        "缺少日期"
      ]
    },
    {
      "type": "memo",
      "name_cn": "备忘录",
      "required_elements": [
        {
          "element": "header",
          "name_cn": "头部信息",
          "format": "To: [recipients]\nFrom: [sender]\nDate: [date]\nSubject: [subject]"
        },
        {
          "element": "body",
          "name_cn": "正文",
          "rules": [
            "简洁明了",
            "直入主题",
            "分点阐述"
          ]
        }
      ],
      "note": "备忘录在考研英语二中较少出现，但需了解基本格式"
    },
    {
      "type": "report",
      "name_cn": "报告",
      "required_elements": [
        {
          "element": "title",
          "name_cn": "标题",
          "rules": [
            "居中",
            "简洁概括报告主题"
          ]
        },
        {
          "element": "body",
          "name_cn": "正文",
          "rules": [
            "开头说明报告背景和目的",
            "主体部分分点或分段展开",
            "结尾给出结论或建议"
          ]
        },
        {
          "element": "signature",
          "name_cn": "署名",
          "rules": [
            "Li Ming"
          ]
        }
      ],
      "note": "报告类题目偶尔出现，格式比书信更灵活"
    }
  ],
  "word_count_guidelines": {
    "requirement": "100词左右",
    "recommended_range": "100-130词",
    "paragraph_distribution": {
      "paragraph_1": "1-2句，开门见山说明目的（约20-30词）",
      "paragraph_2": "2-4句，展开主体内容/要点（约50-70词）",
      "paragraph_3": "1-2句，表达期望/礼貌结尾（约20-30词）"
    },
    "tips": [
      "称呼和落款不计入字数",
      "不要为了凑字数写无关内容",
      "略超100词（110-130词）是安全范围",
      "低于80词会被扣分"
    ]
  }
}

【英语二 大作文写作框架模板 - 柱状图作文模板】
详细框架结构与推荐句型：
{
  "chart_type": "bar_chart",
  "name_cn": "柱状图作文模板",
  "framework": {
    "paragraph_1": {
      "purpose": "描述柱状图数据",
      "template": "As is clearly depicted in the bar chart, [图表主题]. Specifically, [数据描述1]. Meanwhile, [数据描述2]. The most striking feature is that [最显著特征].",
      "example": "As is clearly depicted in the bar chart, the percentage of college students taking part-time jobs varies significantly across different grades. Specifically, only 10% of freshmen engage in part-time work, while the figure rises to 30% for sophomores, 50% for juniors, and reaches a peak of 65% for seniors. The most striking feature is the steady upward trend from freshmen to seniors."
    },
    "paragraph_2": {
      "purpose": "分析原因",
      "template": "Several factors may account for this phenomenon/trend. First and foremost, [原因1及展开]. In addition, [原因2及展开]. Last but not least, [原因3及展开].",
      "example": "Several factors may account for this upward trend. First and foremost, as students progress in their studies, they develop a stronger sense of financial independence and wish to ease their family's financial burden. In addition, senior students have more flexible schedules and fewer courses, which allows them to allocate time to part-time jobs. Last but not least, many students seek practical experience to enhance their competitiveness in the job market."
    },
    "paragraph_3": {
      "purpose": "总结/建议",
      "template": "In conclusion, [总结观点]. It is advisable that [建议]. [展望/号召].",
      "example": "In conclusion, the increasing participation in part-time jobs reflects students' growing awareness of career preparation. It is advisable that students strike a balance between work and study to ensure their academic performance is not compromised. Only in this way can they benefit from both their education and practical experience."
    }
  }
}

【英语二 大作文写作框架模板 - 饼图作文模板】
详细框架结构与推荐句型：
{
  "chart_type": "pie_chart",
  "name_cn": "饼图作文模板",
  "framework": {
    "paragraph_1": {
      "purpose": "描述饼图各部分比例",
      "template": "The pie chart above illustrates [图表主题]. As can be seen, [最大比例项] accounts for the largest proportion at [百分比], followed by [第二项] at [百分比]. [其他项] make up [百分比] and [百分比] respectively. [最小项] constitutes the smallest share at only [百分比].",
      "example": "The pie chart above illustrates how consumers choose restaurants. As can be seen, taste accounts for the largest proportion at 36.3%, followed by service quality at 26.8%. Price and environment make up 20.5% and 12.6% respectively, while other factors constitute the smallest share at only 3.8%."
    },
    "paragraph_2": {
      "purpose": "分析各部分比例背后的原因",
      "template": "The data reveal some interesting insights. The dominance of [最大项] can be attributed to [原因]. Meanwhile, the relatively high proportion of [第二项] suggests that [分析]. It is also noteworthy that [对其他项的分析].",
      "example": "The data reveal some interesting insights. The dominance of taste can be attributed to the fact that food quality is the fundamental factor driving dining choices. Meanwhile, the relatively high proportion of service quality suggests that consumers are increasingly valuing their overall dining experience beyond just the food itself. It is also noteworthy that price is no longer the top concern, indicating a shift in consumer values as living standards improve."
    },
    "paragraph_3": {
      "purpose": "总结/建议",
      "template": "To sum up, [总结]. Based on the above analysis, [建议或展望].",
      "example": "To sum up, the pie chart reflects the diversified factors that influence consumers' restaurant choices, with taste and service being the most valued. Based on the above analysis, restaurant operators should prioritize food quality and service to attract and retain customers."
    }
  }
}

【英语二 大作文写作框架模板 - 折线图作文模板】
详细框架结构与推荐句型：
{
  "chart_type": "line_graph",
  "name_cn": "折线图作文模板",
  "framework": {
    "paragraph_1": {
      "purpose": "描述趋势变化",
      "template": "The line graph demonstrates the changes/trend in [主题] from [起始年] to [终止年]. As is shown, [整体趋势描述]. More specifically, [起始值], then [变化过程], and eventually [最终值/趋势]. A turning point can be observed in [年份], when [转折描述].",
      "example": "The line graph demonstrates the changes in the number of museum visitors from 2013 to 2017. As is shown, there was a consistent upward trend over the five-year period. More specifically, the number started at approximately 6 million in 2013, then climbed steadily, and eventually reached around 9 million in 2017, representing a 50% increase."
    },
    "paragraph_2": {
      "purpose": "分析趋势的原因",
      "template": "There are several reasons behind this trend. To begin with, [原因1]. Furthermore, [原因2]. What is more, [原因3]."
    },
    "paragraph_3": {
      "purpose": "预测/总结",
      "template": "Taking the above factors into consideration, [总结]. It is reasonable to predict/expect that [预测趋势]. [进一步建议]."
    }
  }
}

【英语二 大作文写作框架模板 - 表格作文模板】
详细框架结构与推荐句型：
{
  "chart_type": "table",
  "name_cn": "表格作文模板",
  "framework": {
    "paragraph_1": {
      "purpose": "描述表格关键数据",
      "template": "The table above provides data on [主题]. According to the figures, [关键数据1]. By comparison/In contrast, [关键数据2]. It is worth noting that [最显著特点].",
      "example": "The table above provides data on the changes in China's urban and rural populations from 1990 to 2010. According to the figures, the urban population rose from 300 million in 1990 to 670 million in 2010. By comparison, the rural population decreased from 840 million to 680 million over the same period. It is worth noting that the urban population surpassed the rural population for the first time around 2010."
    },
    "paragraph_2": {
      "purpose": "分析数据变化的原因",
      "template": "This phenomenon can be explained by the following reasons. Firstly, [原因1]. Secondly, [原因2]. Additionally, [原因3]."
    },
    "paragraph_3": {
      "purpose": "总结/预测",
      "template": "In summary, [总结数据反映的趋势/现象]. Looking ahead, [预测]. Therefore, [建议]."
    }
  }
}

【英语一 大作文写作框架模板 - 人生哲理与个人品质类（坚持、乐观、自律、习惯、独立）】
详细框架结构与推荐句型：
{
  "theme_type": "life_philosophy",
  "name_cn": "人生哲理与个人品质类（坚持、乐观、自律、习惯、独立）",
  "applicable_topics": [
    "爬山坚持（2019）",
    "倒掉的牛奶与乐观（2012）",
    "做作业拖延与习惯（2020）",
    "终身学习与阅读（2017/2022）"
  ],
  "framework": {
    "paragraph_1": {
      "purpose": "图画描述段（抓住人物动作神态与文字说明）",
      "template": "As is vividly and subtly portrayed in the cartoon, [图画主体场景及人物行为]. Specifically, [描述关键反差或细节人物1的状态], whereas [对比人物2的状态或行为]. Below the picture is a thought-provoking caption that reads: \"[图画下方文字说明]\". The cartoon conveys far more than what is on the surface.",
      "example": "As is vividly and subtly portrayed in the cartoon, two mountaineers are resting on their journey up a rugged slope. Specifically, one exhausted climber sits down on the ground, lamenting that he cannot go any further, whereas his companion takes a sip of water with determination, encouraging them to keep pressing forward. Below the picture is a thought-provoking caption that reads: \"Halfway Up the Mountain\". The cartoon conveys far more than what is on the surface."
    },
    "paragraph_2": {
      "purpose": "寓意阐释段（揭示哲理本质 + 多维深入归因论证）",
      "template": "The metaphorical implication of the drawing is both profound and inspiring: it is [核心品质词，如perseverance / an optimistic mindset] that constitutes the cornerstone of success and self-fulfillment. To begin with, when confronting bottlenecks and adversity in our daily journey, those armed with [核心品质] tend to view hardships not as insurmountable barriers, but as indispensable stepping stones. Furthermore, historical evidence and contemporary reality abundantly testify that great accomplishments rarely materialize overnight; rather, they are the fruits of persistent endeavor and unwavering conviction.",
      "example": "The metaphorical implication of the drawing is both profound and inspiring: it is perseverance and an indomitable will that constitute the cornerstone of personal growth and self-fulfillment. To begin with, when confronting inevitable bottlenecks in life or academics, those armed with persistence tend to view setbacks not as dead ends, but as indispensable stepping stones toward higher horizons. Furthermore, historical evidence and contemporary reality abundantly testify that monumental breakthroughs rarely materialize overnight; rather, they stem from unflagging dedication despite transient disillusionment."
    },
    "paragraph_3": {
      "purpose": "评论与建议段（结合青年修养提出行动指南 + 倒装升华）",
      "template": "From what has been deliberated above, it is imperative for us, especially contemporary college students, to cultivate [核心品质]. On the individual level, we ought to foster psychological resilience and overcome the tendency of premature surrender. Simultaneously, universities and educators should create supportive environments that nurture perseverance and tenacity. Only by arming ourselves with such a spirit can we surmount looming hurdles and scale the pinnacle of life.",
      "example": "From what has been deliberated above, it is imperative for us, especially contemporary college students, to cultivate unwavering determination in everyday undertakings. On the individual level, we ought to foster inner fortitude and discard the detrimental habit of giving up halfway. Simultaneously, society and universities should encourage a growth-oriented climate that values grit over momentary gains. Only by doing so can we triumph over turbulent waters and scale the pinnacle of our aspirations."
    }
  }
}

【英语一 大作文写作框架模板 - 社会热点与科技生活类（低头族、手机依赖、网络社交疏离、科技双刃剑）】
详细框架结构与推荐句型：
{
  "theme_type": "social_phenomena",
  "name_cn": "社会热点与科技生活类（低头族、手机依赖、网络社交疏离、科技双刃剑）",
  "applicable_topics": [
    "手机时代的聚会（2015）",
    "旅途之余与手机（2011/2013）",
    "信息时代阅读变迁（2018）",
    "人工智能与生活（2025）"
  ],
  "framework": {
    "paragraph_1": {
      "purpose": "图画生动描写（讽刺性画面、反差细节与时代写照）",
      "template": "The cartoon above illustrates a thought-provoking scenario that is exceedingly prevalent in contemporary life. As can be observed, [描述聚会/场景核心细节], each of them [核心动作，如burying their heads into glowing smartphone screens], entirely oblivious to [被忽视的温情或人际互动]. The striking irony in the drawing serves as a mirror reflecting modern social reality.",
      "example": "The cartoon above illustrates a thought-provoking scenario that is exceedingly prevalent in contemporary life. As can be observed, four friends are sitting around a lavish dinner table, but instead of engaging in lively face-to-face conversation, each of them is burying their head in a glowing smartphone screen, entirely oblivious to the warm companionship around them. The striking contrast between physical proximity and emotional alienation serves as a sobering mirror reflecting modern social reality."
    },
    "paragraph_2": {
      "purpose": "深层社会归因（便利性依赖 + 精神浮躁 + 人际退化）",
      "template": "The primary objective of the drawer is not merely to satirize this bizarre scene, but to sound an alarm regarding [核心现象，如digital addiction / interpersonal alienation]. A multitude of underlying factors account for this dilemma. First and foremost, the exponential advancement of digital applications and social algorithms has created a dopamine trap, making individuals increasingly susceptible to virtual distractions. In addition, the frantic pace of modern living exerts immense psychological strain, prompting many to treat smartphones as a safe sanctuary for escapism, which ironically erodes genuine emotional bonds.",
      "example": "The primary objective of the artist is not merely to satirize this scene, but to sound an alarm regarding the growing interpersonal alienation triggered by digital addiction. A multitude of underlying drivers account for this phenomenon. First and foremost, the rapid evolution of mobile technology and algorithmic feeds has created an immersive virtual ecosystem, tempting users into compulsive screen consumption. Furthermore, the high-pressure lifestyle in modern society often leaves individuals emotionally depleted, prompting them to seek instant gratification in virtual cyberspace at the expense of authentic human intimacy."
    },
    "paragraph_3": {
      "purpose": "综合对策与理性呼吁（数字节制、科技向善、重拾温度）",
      "template": "To reverse this worrisome tendency, concerted efforts must be exerted from all sectors of society. For one thing, individuals should exercise digital detox, deliberately unplugging from electronic screens during family gatherings and face-to-face interactions. For another, the media and educational institutions should advocate a healthy technological ethos, reminding the public that technology should serve as a bridge rather than a barrier. It is high time that we embraced real-world connections with sincerity and warmth.",
      "example": "To reverse this worrisome trend, concerted endeavors must be mobilized across society. For one thing, individuals should practice digital discipline and consciously put aside their handsets during interpersonal gatherings. For another, media platforms and communities ought to promote digital well-being campaigns, awakening public awareness to the priceless value of real-life fellowship. It is high time that we mastered technology rather than being enslaved by it."
    }
  }
}

【英语一 大作文写作框架模板 - 传统文化传承与道德风尚类（文化交流融合、孝道关爱、非遗传承、榜样力量）】
详细框架结构与推荐句型：
{
  "theme_type": "cultural_heritage",
  "name_cn": "传统文化传承与道德风尚类（文化交流融合、孝道关爱、非遗传承、榜样力量）",
  "applicable_topics": [
    "文化火锅（2010）",
    "相携/孝道（2014）",
    "家庭教育榜样（2016）",
    "传统节日龙舟赛（2023）"
  ],
  "framework": {
    "paragraph_1": {
      "purpose": "描述象征性意象与文化意境",
      "template": "A close examination of the drawing reveals a captivating and symbolic picture. Centered in the illustration is [核心文化意象，如a boiling hotpot labeled 'Culture' / an aged parent supported by filial children], where [描述融合的元素或温情动作]. The caption succinctly crystallizes the essence with the words: \"[文字说明]\". This imagery immediately commands the viewers' contemplation.",
      "example": "A close examination of the drawing reveals a captivating and symbolic illustration. Centered in the picture is a steamy traditional hotpot labeled 'Culture', in which a myriad of cultural ingredients—ranging from Shakespeare and Einstein to Confucianism and Chinese Kung Fu—are blended harmoniously. The caption succinctly crystallizes the essence with the phrase: 'Cultural Hotpot: Delicious and Nutritious'. This imagery immediately sparks profound contemplation on global cultural dynamics."
    },
    "paragraph_2": {
      "purpose": "阐释文化/道德价值与时代意义",
      "template": "What the painter intends to highlight is the supreme significance of [核心主题，如cultural integration and mutual learning / filial piety and moral integrity]. In the era of globalization, [展开点1：包容借鉴/优秀传统对民族灵魂的重要性]. Furthermore, [展开点2：优良美德对构建和谐社会、连接人心的不可或缺性]. An inclusive and morally grounded mindset not only revitalizes national heritage but also enriches human civilization as a whole.",
      "example": "What the painter intends to underscore is the paramount significance of cross-cultural integration and mutual learning. In an era marked by accelerated globalization, no civilization can flourish in self-imposed isolation; cultural diversity serves as the very lifeblood that propels human progress forward. By assimilating the cream of foreign cultures while cherishing indigenous wisdom, a nation can invigorate its cultural vitality and foster holistic intellectual enrichment."
    },
    "paragraph_3": {
      "purpose": "宏观倡议与青年使命（文化自信、继承创新、知行合一）",
      "template": "In contemplation of the profound message conveyed, we ought to shoulder our responsibility with pride and prudence. We must maintain an open-minded posture toward foreign cultures while holding firm confidence in our own traditional roots. As college students, it is our historical duty to champion cultural dialogues and pass down virtuous moral codes to future generations. Only in this manner can our civilization preserve its timeless brilliance in the global arena.",
      "example": "In contemplation of this inspiring message, we ought to approach cultural diversity with an open mind and steadfast cultural confidence. As young intellectuals in the new era, we are entrusted with the historic mission of bridging distinct civilizations and creatively transforming traditional wisdom. Only by doing so can we build a shared community of shared future and ensure that the beacon of human culture burns brighter than ever."
    }
  }
}

【英语一 大作文写作框架模板 - 生态文明与城市宜居发展类（人与自然、城市公园、绿色生活）】
详细框架结构与推荐句型：
{
  "theme_type": "ecological_urban",
  "name_cn": "生态文明与城市宜居发展类（人与自然、城市公园、绿色生活）",
  "applicable_topics": [
